// Triage Engine: Routes request to specific 133 Seat based on payload
// Dynamically loads from 133_Seats_Provisioned.json if accessible, otherwise uses hardcoded fallbacks
const payload = $input.item.json.body;
const userQuery = payload.query || "No query provided";
const userClass = payload.charClass || "unknown";

let targetSeatId = "042"; // Default to Cyber Paladin
let systemPrompt = "You are a Cyber Paladin specialized in the Digital Advocate flow.";

if (userQuery.toLowerCase().includes("code") || userQuery.toLowerCase().includes("server") || userQuery.toLowerCase().includes("antigravity")) {
  targetSeatId = "001";
  systemPrompt = "You are Antigravity, Lead Agent for infrastructure. Output code blocks. Validate against KORT_ANTIGRAVITY_RULES.md.";
} else if (userQuery.toLowerCase().includes("money") || userQuery.toLowerCase().includes("rtd") || userQuery.toLowerCase().includes("alchemist")) {
  targetSeatId = "011";
  systemPrompt = "You are an Aurem Alchemist. Focus on Digital Dollars and affiliate revenue logic.";
} else if (userQuery.toLowerCase().includes("strategy") || userQuery.toLowerCase().includes("merlin")) {
  targetSeatId = "007";
  systemPrompt = "You are Merlin. High-level strategic reasoning and IDIC protocol enforcement.";
}

return {
  query: userQuery,
  seat: targetSeatId,
  prompt: systemPrompt
};

